import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"Use Directive - v6","description":"Learn about the @use directive in Textwire","frontmatter":{"title":"Use Directive - v6","description":"Learn about the @use directive in Textwire"},"headers":[],"relativePath":"language-elements/directives/use.md","filePath":"src/language-elements/directives/use.md","lastUpdated":1795251319000}`),a={name:`language-elements/directives/use.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="use" tabindex="-1">@use <a class="header-anchor" href="#use" aria-label="Permalink to “@use”">​</a></h1><p><code>@use</code> directives allow you to specify a layout file that will be used to render the current template. This feature is useful for creating reusable layouts that can be applied to multiple templates.</p><p>Example:</p><div class="language-textwire" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">textwire</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">@use(</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;">&quot;layouts/main&quot;</span><span style="--shiki-light:#6F42C1;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">)</span></span></code></pre></div><p>The <code>@use</code> directive accepts a string literal as its argument. This string literal should specify the path to the layout file relative to the <a href="/api/configurations#setting-configurations"><code>TemplateDir</code></a> parameter defined in the configuration. For example, if <a href="/api/configurations#setting-configurations"><code>TemplateDir</code></a> is set to <code>&quot;src/templates&quot;</code> and you have <code>layouts</code> directory in there, you can use the layout directive like <code>@use(&quot;layouts/main&quot;)</code>, and it will look for the layout file at <code>&quot;src/templates/layouts/main.tw&quot;</code>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">Understanding the @use Directive</p><p>When you use the <code>@use</code> directive, only the content inside <a href="/language-elements/directives/insert"><code>@insert</code></a> directives will be rendered; the rest of the file&#39;s content will be ignored. This is because the <code>@use</code> takes the layout file as a base instead of rendering the current file directly. During this process, all placeholders reserved in the layout file are populated with the content specified within your inserts.</p></div><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li><strong>Name is a constant.</strong> The first argument (name) is the constant, it cannot be dynamic, only literal strings are allowed.</li><li><strong>Use path alias.</strong> If your layouts are located in the <code>layouts</code> directory, you can use the <code>~</code> alias to reference them. Read about <a href="/faq#what-are-the-path-aliases">Path Aliases</a>.</li><li><strong>Only one <code>@use</code> allowed.</strong> Only one <code>@use</code> directive is allowed per template file. Defining multiple layouts will cause an error.</li><li><strong>Recommended at the beginning.</strong> You can place <code>@use</code> anywhere in the template, but it’s <strong>recommended to put it on the first line</strong> for clarity.</li><li><strong>Not allowed in layouts.</strong> Defining <code>@use</code> inside a <strong>layout file</strong> will always result in an error. This is intentional to keep layouts simple.</li></ul><ul><li><strong>Don&#39;t use the same file as a component and a layout.</strong> A component is rendered with slots and passes, while a layout is rendered with inserts and reserves. The same file can&#39;t correctly serve both roles, so keep component files and layout files separate.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};